fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut chars_rev = txt.chars().rev();

    // Get the last character
    let last_char = match chars_rev.next() {
        Some(c) => c,
        None => return false, // empty string
    };

    // Check if the last character is ASCII alphabetic
    if !last_char.is_ascii_alphabetic() {
        return false;
    }

    // Check the character before last, if any
    match chars_rev.next() {
        None => true,            // string length is 1, condition satisfied
        Some(prev_char) => prev_char == ' ', // prev char must be space
    }
}